import { useEffect, useRef, useState } from "react";

export default function CameraCapture({ onCapture }) {
  const videoRef = useRef(null);
  const streamRef = useRef(null);
  const [captured, setCaptured] = useState("");
  const [cameraError, setCameraError] = useState("");

  useEffect(() => {
    navigator.mediaDevices
      .getUserMedia({ video: { facingMode: "user" } })
      .then((stream) => {
        streamRef.current = stream;
        if (videoRef.current) videoRef.current.srcObject = stream;
      })
      .catch(() => setCameraError("Camera access was denied or unavailable."));

    return () => {
      if (streamRef.current) {
        streamRef.current.getTracks().forEach((track) => track.stop());
      }
    };
  }, []);

  const capture = () => {
    const video = videoRef.current;
    if (!video || !video.videoWidth) return;

    const canvas = document.createElement("canvas");
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext("2d");
    ctx.drawImage(video, 0, 0);
    const dataUrl = canvas.toDataURL("image/png");
    setCaptured(dataUrl);
    onCapture(dataUrl);
  };

  const reset = () => {
    setCaptured("");
    onCapture("");
  };

  return (
    <div className="glass-card p-4 space-y-3">
      {cameraError ? (
        <p className="text-sm text-red-600">{cameraError}</p>
      ) : captured ? (
        <img src={captured} alt="captured eye" className="w-full rounded-xl" />
      ) : (
        <video ref={videoRef} autoPlay playsInline className="w-full rounded-xl bg-slate-200" />
      )}
      <div className="flex gap-2">
        <button onClick={capture} className="bg-medBlue text-white px-4 py-2 rounded-lg hover-lift">Capture</button>
        {captured && (
          <button onClick={reset} className="bg-slate-200 px-4 py-2 rounded-lg hover-lift">Retake</button>
        )}
      </div>
    </div>
  );
}
